ALTER TABLE `resources` ADD COLUMN IF NOT EXISTS `media_width` smallint unsigned DEFAULT NULL AFTER `media_synced_at`;
ALTER TABLE `resources` ADD COLUMN IF NOT EXISTS `media_height` smallint unsigned DEFAULT NULL AFTER `media_width`;
ALTER TABLE `resources` ADD COLUMN IF NOT EXISTS `media_source_meta` json DEFAULT NULL AFTER `media_height`;
ALTER TABLE `resources` ADD COLUMN IF NOT EXISTS `media_sync_message` text DEFAULT NULL AFTER `media_source_meta`;
